var t=`0191-panna-cotta`;var a=`world-0191`;var n=`IT`;var s=`southern-europe`;var r=6;var o=251;var l={en:`Panna Cotta`,ua:`Пана-кота`};var m={en:`A classic dish from Italy, featuring heavy cream, whole cow milk, raspberry. A practical home-kitchen version with measured step ingredients and clear cooking methods.`,ua:`Класична страва з Італія. Основні складники: вершки високої жирності, цільне коров'яче молоко, малина. Домашній варіант із поетапними діями та точними кількостями продуктів.`};var g=[{en:`Combine these ingredients in a pot, bring just to a boil and skim any foam. Simmer gently for about 7 minutes to make a flavorful base.`,ua:`З’єднайте складники в каструлі, доведіть майже до кипіння та зніміть піну. Варіть на малому вогні приблизно 7 хвилин для насиченої основи.`,t:[`simmering`,`skimming-foam`],m:7,i:[[`heavy-cream`,520,`ml`],[`whole-cow-milk`,200,`ml`],[`white-granulated-sugar`,90,`g`],[`vanilla-extract`,5,`ml`]]},{en:`Dissolve or bloom the setting ingredients as directed, combine with the base and refrigerate for about 240 minutes until fully set.`,ua:`Підготуйте желювальні складники за інструкцією, змішайте з основою та охолоджуйте приблизно 240 хвилин до повного застигання.`,t:[`gelatin-setting`,`rapid-chilling`],m:240,i:[[`gelatin-powder`,11,`g`],[`water`,55,`ml`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:4,i:[[`raspberry`,230,`g`]]}];var u={slug:t,id:a,country:`IT`,region:s,servings:6,minutes:251,title:l,text:m,steps:g};export{n as country,u as default,a as id,o as minutes,s as region,r as servings,t as slug,g as steps,m as text,l as title};